// Generated by npm run build:browser. Edit model.js and app.js instead.
(() => {
"use strict";
// ZB202 research prototype. Every airflow value here is an assumed effective
// outdoor-air rate, not a BMS measurement or a command to physical equipment.
const DEFAULTS = Object.freeze({
  stepMinutes: 5,
  widthM: 5.9,
  lengthM: 7.9,
  heightM: 6.1,
  outdoorCo2Ppm: 420,
  co2GenerationM3PerHourPerson: 0.018,
  targetCo2Ppm: 800,
  initialCo2Ppm: 600,
  airflowChoicesM3h: [100, 200, 300, 450, 600],
  fixedAirflowM3h: 300,
});

const roomVolumeM3 = (config = DEFAULTS) => config.widthM * config.lengthM * config.heightM;

function random(seed) {
  let state = seed >>> 0;
  return () => {
    state += 0x6d2b79f5;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

// Occupants arrive in groups and stay for multiple steps. This is a scenario
// generator for software experiments, not a model learned from ZB202 people.
function generateOccupancy(seed, steps = 288) {
  const draw = random(seed);
  const counts = [];
  let occupants = 0;
  let remaining = 0;
  for (let step = 0; step < steps; step += 1) {
    const hour = step / 12;
    if (remaining > 0) {
      remaining -= 1;
      if (draw() < 0.035) occupants = Math.max(0, occupants - 1);
      if (remaining === 0) occupants = 0;
    } else {
      const active = (hour >= 9 && hour < 12) || (hour >= 13 && hour < 18);
      const arrivalProbability = active ? 0.075 : hour >= 8 && hour < 19 ? 0.012 : 0.001;
      if (draw() < arrivalProbability) {
        occupants = 1 + Math.floor(draw() * 10);
        remaining = 4 + Math.floor(draw() * 21); // 20–120 minutes
      }
    }
    counts.push(occupants);
  }
  return counts;
}

function trainTimeVaryingMarkov(days = 120, seed = 1000, steps = 288) {
  const states = 11;
  const global = Array.from({ length: states }, () => Array(states).fill(0.2));
  const local = Array.from({ length: steps }, () => Array.from({ length: states }, () => Array(states).fill(0)));
  for (let day = 0; day < days; day += 1) {
    const trace = generateOccupancy(seed + day, steps);
    for (let t = 0; t < steps - 1; t += 1) {
      global[trace[t]][trace[t + 1]] += 1;
      for (let offset = -6; offset <= 6; offset += 1) {
        const slot = (t + offset + steps) % steps;
        local[slot][trace[t]][trace[t + 1]] += 1 - Math.abs(offset) / 7;
      }
    }
  }
  const globalProbabilities = global.map((row) => normalize(row));
  return local.map((matrix) => matrix.map((row, from) => normalize(
    row.map((count, to) => count + 3 * globalProbabilities[from][to]),
  )));
}

function normalize(row) {
  const total = row.reduce((sum, value) => sum + value, 0);
  return row.map((value) => value / total);
}

function forecastOccupancy(currentCount, startStep, matrices, horizon = 24) {
  let distribution = Array(11).fill(0);
  distribution[currentCount] = 1;
  const forecast = [];
  for (let offset = 0; offset < horizon; offset += 1) {
    forecast.push({
      expected: distribution.reduce((sum, probability, count) => sum + probability * count, 0),
      probabilityOccupied: 1 - distribution[0],
    });
    const transition = matrices[(startStep + offset) % matrices.length];
    const next = Array(11).fill(0);
    for (let from = 0; from < 11; from += 1) {
      for (let to = 0; to < 11; to += 1) next[to] += distribution[from] * transition[from][to];
    }
    distribution = next;
  }
  return forecast;
}

function nextCo2Ppm(currentPpm, occupancy, effectiveOutdoorAirM3h, config = DEFAULTS) {
  const volume = roomVolumeM3(config);
  const hours = config.stepMinutes / 60;
  const generationPpmM3h = 1e6 * config.co2GenerationM3PerHourPerson * occupancy;
  if (effectiveOutdoorAirM3h <= 0) return currentPpm + generationPpmM3h * hours / volume;
  const equilibrium = config.outdoorCo2Ppm + generationPpmM3h / effectiveOutdoorAirM3h;
  return equilibrium + (currentPpm - equilibrium) * Math.exp(-effectiveOutdoorAirM3h * hours / volume);
}

function choosePredictiveAirflow(currentPpm, currentCount, previousAirflow, startStep, matrices, config = DEFAULTS) {
  const forecast = forecastOccupancy(currentCount, startStep, matrices);
  let beam = [{ ppm: currentPpm, airflow: previousAirflow, cost: 0, first: null }];
  for (const prediction of forecast) {
    const candidates = [];
    for (const path of beam) {
      for (const airflow of config.airflowChoicesM3h) {
        const ppm = nextCo2Ppm(path.ppm, prediction.expected, airflow, config);
        const excess = Math.max(0, ppm - config.targetCo2Ppm) / 100;
        const iaqCost = prediction.probabilityOccupied * excess ** 2;
        const airCost = 0.10 * airflow / Math.max(...config.airflowChoicesM3h);
        const changeCost = 0.02 * Math.abs(airflow - path.airflow) / Math.max(...config.airflowChoicesM3h);
        candidates.push({ ppm, airflow, cost: path.cost + iaqCost + airCost + changeCost, first: path.first ?? airflow });
      }
    }
    candidates.sort((a, b) => a.cost - b.cost);
    beam = candidates.slice(0, 32);
  }
  return beam[0].first;
}

function simulatePolicy(occupancy, policy, matrices, config = DEFAULTS) {
  let ppm = config.initialCo2Ppm;
  let previousAirflow = config.airflowChoicesM3h[0];
  const rows = [];
  for (let step = 0; step < occupancy.length; step += 1) {
    const people = occupancy[step];
    const airflow = policy === "fixed" ? config.fixedAirflowM3h
      : policy === "reactive" ? config.airflowChoicesM3h.find((choice) => choice >= 100 + 50 * people) ?? config.airflowChoicesM3h.at(-1)
        : choosePredictiveAirflow(ppm, people, previousAirflow, step, matrices, config);
    ppm = nextCo2Ppm(ppm, people, airflow, config);
    rows.push({ step, people, airflowM3h: airflow, co2Ppm: ppm });
    previousAirflow = airflow;
  }
  const occupied = rows.filter((row) => row.people > 0);
  return {
    policy,
    rows,
    summary: {
      occupiedSteps: occupied.length,
      occupiedMinutesAboveTarget: occupied.filter((row) => row.co2Ppm > config.targetCo2Ppm).length * config.stepMinutes,
      peakCo2Ppm: Math.round(Math.max(...rows.map((row) => row.co2Ppm))),
      meanOccupiedCo2Ppm: occupied.length ? Math.round(occupied.reduce((sum, row) => sum + row.co2Ppm, 0) / occupied.length) : null,
      totalOutdoorAirM3: Math.round(rows.reduce((sum, row) => sum + row.airflowM3h * config.stepMinutes / 60, 0)),
      airflowChanges: rows.filter((row, index) => index > 0 && row.airflowM3h !== rows[index - 1].airflowM3h).length,
    },
  };
}

function runExperiment(seed = 20260929, config = DEFAULTS) {
  const occupancy = generateOccupancy(seed);
  // Separate seeds prevent using the evaluation day's future occupancy in training.
  const matrices = trainTimeVaryingMarkov(120, 1000);
  return {
    seed,
    config,
    volumeM3: roomVolumeM3(config),
    occupancy,
    results: ["fixed", "reactive", "predictive"].map((policy) => simulatePolicy(occupancy, policy, matrices, config)),
  };
}


const seedInput = document.getElementById("seed");
const initialInput = document.getElementById("initial-co2");
const summary = document.getElementById("summary");
const chart = document.getElementById("chart");
const liveStatus = document.getElementById("live-status");
const liveButton = document.getElementById("use-live");
const occupancyStep = document.getElementById("occupancy-step");
const occupancyTime = document.getElementById("occupancy-time");
const occupancyCount = document.getElementById("occupancy-count");
const occupancyBars = document.getElementById("occupancy-bars");
const names = { fixed: "固定通风", reactive: "当前人数响应", predictive: "预测控制" };
let latestLive = null;
let experiment;

function pathFor(values, min, max, width, height) {
  return values.map((value, index) => `${index ? "L" : "M"}${(index / (values.length - 1) * width).toFixed(1)},${(height - (value - min) / (max - min) * height).toFixed(1)}`).join(" ");
}

function renderChart(data) {
  const width = 960;
  const height = 260;
  const traces = Object.fromEntries(data.results.map((item) => [item.policy, item.rows.map((row) => row.co2Ppm)]));
  const maxPpm = Math.max(1200, Math.ceil(Math.max(...Object.values(traces).flat()) / 200) * 200);
  const horizontal = [400, 600, 800, 1000, 1200].filter((value) => value <= maxPpm);
  chart.innerHTML = `<svg viewBox="0 0 ${width + 65} ${height + 38}" preserveAspectRatio="none" aria-hidden="true">
    ${horizontal.map((value) => `<line class="grid" x1="0" x2="${width}" y1="${height - (value - 350) / (maxPpm - 350) * height}" y2="${height - (value - 350) / (maxPpm - 350) * height}"/><text class="axis" x="${width + 9}" y="${height - (value - 350) / (maxPpm - 350) * height + 4}">${value}</text>`).join("")}
    <path class="target" d="${pathFor(Array(288).fill(data.config.targetCo2Ppm), 350, maxPpm, width, height)}"/>
    ${Object.entries(traces).map(([policy, values]) => `<path class="${policy}" d="${pathFor(values, 350, maxPpm, width, height)}"/>`).join("")}
    <path class="people" d="${pathFor(data.occupancy, 0, 10, width, height)}"/>
    ${[0, 6, 12, 18, 24].map((hour) => `<text class="axis" x="${hour / 24 * width}" y="${height + 26}" text-anchor="${hour === 0 ? "start" : hour === 24 ? "end" : "middle"}">${String(hour).padStart(2, "0")}:00</text>`).join("")}
  </svg>`;
}

function render(data) {
  renderOccupancy(data);
  summary.innerHTML = data.results.map(({ policy, summary: metric }) => `<article class="result ${policy}">
    <h3>${names[policy]}</h3><div><span>占用时超过目标</span><strong>${metric.occupiedMinutesAboveTarget} min</strong></div>
    <div><span>占用时平均 CO₂</span><strong>${metric.meanOccupiedCo2Ppm ?? "—"} ppm</strong></div>
    <div><span>全天 CO₂ 峰值</span><strong>${metric.peakCo2Ppm} ppm</strong></div>
    <div><span>累计室外空气量</span><strong>${metric.totalOutdoorAirM3} m³</strong></div>
    <div><span>风量切换次数</span><strong>${metric.airflowChanges}</strong></div>
  </article>`).join("");
  renderChart(data);
}

function renderOccupancy(data) {
  const people = data.occupancy;
  occupancyStep.max = String(people.length - 1);
  const firstOccupied = people.findIndex((count) => count > 0);
  occupancyStep.value = String(firstOccupied < 0 ? 0 : firstOccupied);
  occupancyBars.innerHTML = `<svg viewBox="0 0 288 80" preserveAspectRatio="none">${people.map((count, step) => `<rect x="${step}" y="${80 - count * 7}" width="1" height="${count * 7}"/>`).join("")}</svg>`;
  document.getElementById("occupancy-peak").textContent = String(Math.max(...people));
  document.getElementById("occupancy-minutes").textContent = String(people.filter((count) => count > 0).length * data.config.stepMinutes);
  showOccupancyStep();
}

function showOccupancyStep() {
  if (!experiment) return;
  const step = Number(occupancyStep.value);
  occupancyTime.textContent = `${String(Math.floor(step / 12)).padStart(2, "0")}:${String(step % 12 * 5).padStart(2, "0")}`;
  occupancyCount.textContent = String(experiment.occupancy[step]);
  occupancyStep.setAttribute("aria-valuetext", `${occupancyTime.textContent}，模拟 ${experiment.occupancy[step]} 人`);
}

function run() {
  const seed = Number(seedInput.value);
  const initialCo2Ppm = Number(initialInput.value);
  if (!Number.isInteger(seed) || seed < 1 || seed > 4294967295 || !Number.isFinite(initialCo2Ppm) || initialCo2Ppm < 350 || initialCo2Ppm > 3000) {
    window.alert("请输入有效的随机种子和 350–3000 ppm 的初始 CO₂。");
    return;
  }
  experiment = runExperiment(seed, { ...DEFAULTS, initialCo2Ppm });
  render(experiment);
}

function csvCell(value) { return String(value).replaceAll('"', '""'); }
function downloadCsv() {
  const header = "step,time,simulated_people,fixed_co2_ppm,fixed_outdoor_air_m3h,reactive_co2_ppm,reactive_outdoor_air_m3h,predictive_co2_ppm,predictive_outdoor_air_m3h";
  const [fixed, reactive, predictive] = experiment.results.map((result) => result.rows);
  const rows = fixed.map((row, index) => [index, `${String(Math.floor(index / 12)).padStart(2, "0")}:${String(index % 12 * 5).padStart(2, "0")}`, row.people, fixed[index].co2Ppm.toFixed(1), fixed[index].airflowM3h, reactive[index].co2Ppm.toFixed(1), reactive[index].airflowM3h, predictive[index].co2Ppm.toFixed(1), predictive[index].airflowM3h].map(csvCell).join(","));
  const csv = [header, ...rows].join("\n");
  const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = `zb202-simulation-seed-${experiment.seed}.csv`;
  anchor.click();
  URL.revokeObjectURL(url);
}

function connectBridge() {
  const socket = new WebSocket("ws://127.0.0.1:8787");
  const timeout = window.setTimeout(() => { if (!latestLive) liveStatus.textContent = "本地桥接未提供 CO₂ 数据"; }, 5000);
  socket.addEventListener("message", (event) => {
    let message;
    try { message = JSON.parse(event.data); } catch { return; }
    if (message.type !== "telemetry") return;
    const ppm = Number(message.values?.co2);
    const timestamp = Date.parse(message.receivedAt);
    if (!Number.isFinite(ppm) || ppm < 350 || ppm > 3000 || !Number.isFinite(timestamp) || Date.now() - timestamp > 15 * 60 * 1000) return;
    if (!latestLive || timestamp > latestLive.timestamp) {
      latestLive = { ppm, timestamp, device: message.deviceId || message.devEui || "CO₂ sensor" };
      liveButton.disabled = false;
      liveStatus.textContent = `最新实测：${Math.round(ppm)} ppm · ${latestLive.device} · ${new Date(timestamp).toLocaleTimeString()}`;
      window.clearTimeout(timeout);
    }
  });
  socket.addEventListener("error", () => { if (!latestLive) liveStatus.textContent = "本地桥接不可用；可继续离线仿真"; });
  socket.addEventListener("close", () => { if (!latestLive) liveStatus.textContent = "本地桥接未连接；可继续离线仿真"; });
}

document.getElementById("run").addEventListener("click", run);
document.getElementById("download").addEventListener("click", downloadCsv);
occupancyStep.addEventListener("input", showOccupancyStep);
liveButton.addEventListener("click", () => {
  if (!latestLive) return;
  if (Date.now() - latestLive.timestamp > 15 * 60 * 1000) {
    liveButton.disabled = true;
    liveStatus.textContent = "实测 CO₂ 已超过 15 分钟，请等待新读数";
    return;
  }
  initialInput.value = String(Math.round(latestLive.ppm));
  run();
});
run();
connectBridge();

})();
